// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        // Ensure rewardToken is not zero to avoid revert during addReward (require newOwner != address(0) not relevant here)
        vm.assume(rewardToken != address(0));

        // Call addReward to trigger the bug: the bug modifies transferOwnership indirectly via modifier onlyOwner? 
        // Actually addReward does not change owner, but the bug in transferOwnership does not affect addReward.
        // Instead the test should probe transferOwnership after addReward.
        // Since addReward is onlyOwner, we first need to ensure we are the owner.
        c.addReward(rewardToken);

        // Now test if transferOwnership works (should succeed in reference, fail in mutant)
        // Create a new address to transfer to
        address newOwner = address(0x1234);

        // Try to call transferOwnership indirectly via a wrapper that catches revert
        bool success;
        bytes memory data = abi.encodeWithSelector(c.transferOwnership.selector, newOwner);
        (success, ) = address(c).call(data);

        // Assert that the call succeeded (reference: true, mutant: false due to added false in require)
        assertTrue(success, "transferOwnership should succeed after addReward");
    }
}

